            font-weight: 500;
            cursor: pointer;
            transition: background-color 0.2s;
        }

        .btn-outline {
            background-color: transparent;
            border: 1px solid var(--border-color);
            color: var(--text-color);
        }

        .btn-outline:hover {
            background-color: var(--bg-color);
        }

        .btn-danger {
            background-color: var(--danger-color);
            color: white;
        }

        .btn-danger:hover {
            background-color: var(--danger-hover);
        }

        /* Native dialog styling */
        dialog {
            padding: 0;
            border: none;
            border-radius: var(--border-radius);
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
            max-width: 400px;
            width: 90%;
            background: var(--surface-color);
            color: var(--text-color);
        }

        dialog::backdrop {
            background-color: var(--overlay-bg);
            backdrop-filter: blur(2px);
        }

        .dialog-content {
            padding: 24px;
        }

        .dialog-header {
            margin-top: 0;
            margin-bottom: 8px;
            font-size: 1.25rem;
            font-weight: 600;
        }

        .dialog-body {
            color: var(--text-muted);
            margin-bottom: 24px;
            line-height: 1.5;
        }

        .dialog-footer {
            display: flex;
            justify-content: flex-end;
            gap: 12px;
        }
    </style>
</head>
<body>

    <main class="preview-container">
        <div class="image-placeholder">
            [Image Preview]
        </div>
        <div class="actions">
            <!-- Utilizing command/commandfor for minimal JS, fallback JS provided for older browsers -->
            <button type="button" class="btn-danger trigger" id="deleteTrigger" command="show-modal" commandfor="deleteConfirmDialog">
                Delete
            </button>
        </div>
    </main>

    <!-- Accessible Native Dialog -->
    <dialog id="deleteConfirmDialog" aria-labelledby="dialog-title">
        <div class="dialog-content">
            <h2 id="dialog-title" class="dialog-header">Delete Image?</h2>
            <p class="dialog-body">Are you sure you want to delete this image from your library? This action cannot be undone.</p>

            <div class="dialog-footer">
                <button type="button" class="btn-outline" command="close" commandfor="deleteConfirmDialog" data-close>Cancel</button>
                <button type="button" class="btn-danger" command="close" commandfor="deleteConfirmDialog" value="delete" data-confirm>Delete</button>
            </div>
        </div>
    </dialog>

    <script>
        // React-style component structure for managing logic
        const ImagePreviewApp = () => {
            const dialog = document.getElementById('deleteConfirmDialog');
            const trigger = document.getElementById('deleteTrigger');

            // Check if browser supports command attribute
            const supportsCommand = 'command' in HTMLButtonElement.prototype;

            // Fallback for browsers without command/commandfor support
            if (!supportsCommand) {
                trigger.addEventListener('click', () => {
                    dialog.showModal();
                });

                const closeBtn = dialog.querySelector('[data-close]');
                const confirmBtn = dialog.querySelector('[data-confirm]');

                closeBtn.addEventListener('click', () => dialog.close('cancel'));

                confirmBtn.addEventListener('click', () => {
                    // Logic for deletion would go here
                    console.log('Image deleted');
                    dialog.close('delete');
                });
            }

            // Listen for close event to handle result, works with both native command and fallback
            dialog.addEventListener('close', () => {
                if (dialog.returnValue === 'delete') {
                    console.log('Action: Image deleted');
                    // In a real React app, this would update state or trigger a callback
                } else {
                    console.log('Action: Cancelled');
                }
            });
        };

        // Initialize
        document.addEventListener('DOMContentLoaded', ImagePreviewApp);
    </script>
</body>
</html>
